<?php
namespace App\Http\Controllers;
use App\Models\TenantSupportRequest;use App\Models\Landlord\PlatformSupportCase;use App\Services\Landlord\TenantContext;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class TenantSupportRequestController extends Controller {public function index(Request $request):View{$user=$request->user();return view('support.index',['requests'=>TenantSupportRequest::query()->where('submitted_by_user_id',$user->id)->latest()->get(),'canSubmitProblem'=>$user->can('support.problems.submit'),'canSubmitSuggestion'=>$user->can('support.suggestions.submit'),'canManage'=>$user->can('support.manage')]);}public function store(Request $request):RedirectResponse{$data=$request->validate(['type'=>['required','in:problem,suggestion'],'subject'=>['required','string','max:180'],'message'=>['required','string','max:5000'],'priority'=>['nullable','in:normal,high,critical'],'reported_url'=>['nullable','string','max:2048']]);abort_unless($request->user()->can($data['type']===TenantSupportRequest::TYPE_PROBLEM?'support.problems.submit':'support.suggestions.submit'),403);if ($data['type']!==TenantSupportRequest::TYPE_PROBLEM) $data['priority']=null;$data['browser_info']=mb_substr((string)$request->userAgent(),0,1000);TenantSupportRequest::query()->create($data+['submitted_by_user_id'=>$request->user()->id]);return back()->with('status','Your request was submitted.');}public function manage():View{$tenant=app(TenantContext::class)->tenant();$requests=TenantSupportRequest::query()->with('submittedBy')->latest()->get();$cases=PlatformSupportCase::query()->where('tenant_id',$tenant->id)->get()->keyBy('tenant_support_request_id');return view('support.manage',['requests'=>$requests,'platformCases'=>$cases,'openCount'=>TenantSupportRequest::query()->whereIn('status',['submitted','under_review'])->count()]);}public function update(Request $request,TenantSupportRequest $supportRequest):RedirectResponse{$data=$request->validate(['status'=>['required','in:submitted,under_review,planned,in_progress,released,declined,forwarded'],'tenant_admin_note'=>['nullable','string','max:5000'],'forward'=>['nullable','boolean']]);$supportRequest->fill(['status'=>$data['status'],'tenant_admin_note'=>$data['tenant_admin_note']??null]);if($request->boolean('forward')){$supportRequest->fill(['status'=>'forwarded','forwarded_by_user_id'=>$request->user()->id,'forwarded_at'=>now()]);$tenant=app(TenantContext::class)->tenant();PlatformSupportCase::query()->updateOrCreate(['tenant_id'=>$tenant->id,'tenant_support_request_id'=>$supportRequest->id],['type'=>$supportRequest->type,'status'=>'forwarded','subject'=>$supportRequest->subject,'message'=>$supportRequest->message,'forwarded_at'=>now()]);}$supportRequest->save();return back()->with('status','Request updated.');}}
